<?php require"config/auth.php";require"config/db.php";if(isset($_GET["delete"])){$id=(int)$_GET["delete"];$conn->query("DELETE FROM books WHERE id=$id");header("Location:books.php");exit;}if($_SERVER["REQUEST_METHOD"]==="POST"){$t=trim($_POST["title"]);$a=trim($_POST["author"]);$i=trim($_POST["isbn"]);$c=trim($_POST["category"]);$q=(int)$_POST["quantity"];$s=$conn->prepare("INSERT INTO books(title,author,isbn,category,quantity,available) VALUES(?,?,?,?,?,?)");$s->bind_param("ssssii",$t,$a,$i,$c,$q,$q);$s->execute();header("Location:books.php");exit;}$q=trim($_GET["q"]??"");$sql="SELECT * FROM books";if($q!==""){$x=$conn->real_escape_string($q);$sql.=" WHERE title LIKE '%$x%' OR author LIKE '%$x%' OR category LIKE '%$x%'";}$rows=$conn->query($sql." ORDER BY id DESC");?><!doctype html><html><head><title>Books</title><link rel="stylesheet" href="assets/style.css"></head><body><?php include"nav.php";?><main class="container"><h1>Books</h1><div class="card"><h2>Add Book</h2><form method="post" class="grid"><div><label>Title</label><input name="title" required></div><div><label>Author</label><input name="author" required></div><div><label>ISBN</label><input name="isbn"></div><div><label>Category</label><input name="category"></div><div><label>Quantity</label><input type="number" name="quantity" min="1" value="1" required></div><div style="align-self:end"><button class="btn">Add Book</button></div></form></div><div class="card"><form><input class="search" name="q" value="<?=htmlspecialchars($q)?>" placeholder="Search books..."><button class="btn">Search</button></form><table><tr><th>ID</th><th>Title</th><th>Author</th><th>Category</th><th>Qty</th><th>Available</th><th>Action</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=$r["id"]?></td><td><?=htmlspecialchars($r["title"])?></td><td><?=htmlspecialchars($r["author"])?></td><td><?=htmlspecialchars($r["category"])?></td><td><?=$r["quantity"]?></td><td><?=$r["available"]?></td><td><a class="btn danger" href="?delete=<?=$r["id"]?>" onclick="return confirm('Delete this book?')">Delete</a></td></tr><?php endwhile;?></table></div></main></body></html>